sp_widget.client_script:
function($scope, $rootScope, $timeout) {
    var chartInstanceBimestre = null;

    $scope.anoSelecionadoBimestre = "";
    $scope.bimestreSelecionadoBimestre = "";
    $scope.exibirGraficoBimestre = false;

     function carregarDadosDoServer() {
        var filtros = {
            ano: $scope.anoSelecionadoBimestre || "",
            bimestre: $scope.bimestreSelecionadoBimestre || ""
        };

        $scope.server.get(filtros).then(function(response) {
            var listaDados = response.data.dadosGraficoBarras || [];
            $timeout(function() {
                inicializarGrafico(listaDados);
            }, 300);
        });
    }

    $rootScope.$on('filtroAnoSelecionado', function(event, ano) {
        $scope.anoSelecionadoBimestre = ano;
        carregarDadosDoServer();
    });

    $rootScope.$on('filtroBimestreSelecionado', function(event, bimestre) {
        $scope.bimestreSelecionadoBimestre = bimestre;
        carregarDadosDoServer();
    });

    carregarDadosDoServer();

    function inicializarGrafico(listaDados) {
        if (!listaDados || listaDados.length === 0) {
            if (chartInstanceBimestre) {
                chartInstanceBimestre.destroy();
                chartInstanceBimestre = null;
            }
            $scope.exibirGraficoBimestre = false;
            $scope.$applyAsync();
            return;
        }

        $scope.exibirGraficoBimestre = true;
        $scope.$applyAsync();

        var labels = [];
        var resultadoData = [];

        for (var i = 0; i < listaDados.length; i++) {
            var label = '';
            if ($scope.anoSelecionadoBimestre) {
                label = listaDados[i].bimestre + 'º Bim';
            } else {
                label = listaDados[i].ano;
            }
            labels.push(label);
            resultadoData.push(listaDados[i].resultado / 1);
        }

        var backgroundColors = [];
        var borderColors = [];

        for (var j = 0; j < resultadoData.length; j++) {
            if (resultadoData[j] >= 0) {
                backgroundColors.push('#4b77bf'); // Azul para positivo
                borderColors.push('#4b77bf');
            } else {
                backgroundColors.push('#D90C0C'); // Vermelho para negativo
                borderColors.push('#D90C0C');
            }
        }

        var contexto = document.getElementById('graficoResultadoBimestre').getContext('2d');

        if (chartInstanceBimestre) {
            chartInstanceBimestre.destroy();
        }

        chartInstanceBimestre = new Chart(contexto, {
            type: 'bar',
            data: {
                labels: labels,
                datasets: [
                    {
                        label: 'Resultado Primário',
                        data: resultadoData,
                        backgroundColor: backgroundColors,
                        borderColor: borderColors,
                        borderWidth: 1
                    }
                ]
            },
            options: {
                responsive: true,
                maintainAspectRatio: false,
                scales: {
                    x: {
                        stacked: false,
                        title: {
                            display: true,
                            text: $scope.anoSelecionadoBimestre ? 'Bimestre' : 'Ano'
                        },
                        barPercentage: 1.0,
                        categoryPercentage: 1.0
                    },
                    y: {
                        beginAtZero: true,
                        title: {
                            display: true,
                            text: 'Valor em R$'
                        },
                        ticks: {
                            callback: function(value) {
                                return 'R$ ' + value.toLocaleString('pt-BR') + '';
                            }
                        }
                    }
                },
                plugins: {
                    legend: {
                        display: true,
                        position: 'top'
                    },
                    tooltip: {
                        callbacks: {
                            label: function(context) {
                                return context.dataset.label + ': R$ ' + context.parsed.y.toLocaleString('pt-BR') + '';
                            }
                        }
                    }
                }
            }
        });
    }
}

sp_widget.css:
canvas {
  display: block;
  margin: 0 auto;
}

h3, div, span {
 font-family: 'Roboto Flex', sans-serif;
}
.titleEnd{
   font-family: Roboto;
  font-weight: 500;
  font-style: Medium;
  font-size: 24px;
  leading-trim: NONE;
  line-height: 100%;
  letter-spacing: 0%;
	color:#021770;
}


/* --- Media Queries para Responsividade --- */

/* Telas Pequenas (Mobile S, M, L - até 767px) */
@media (max-width: 767px) {
  canvas {
    max-width: 90%; /* Ajustar a largura máxima do canvas */
  }
  h3 {
    font-size: 1rem; /* Ajustar o tamanho da fonte do título */
  }
}

/* Tablets (iPad Mini, iPad Air, Surface Duo, Galaxy Z Fold 5 - 768px até 1023px) */
@media (min-width: 768px) and (max-width: 1023px) {
  canvas {
    max-width: 80%;
  }
  h3 {
    font-size: 1.1rem;
  }
}

/* Laptops e Telas Maiores (iPad Pro, Surface Pro 7, Laptops, 4K - 1024px em diante) */
@media (min-width: 1024px) {
  canvas {
    max-width: none;
  }
  h3 {
  }
}

/* Ajustes para o Surface Duo (540x720) */
@media (width: 540px) and (height: 720px) {
    canvas {
        max-width: 95%;
    }
}

/* Ajustes para Galaxy Z Fold 5 (max-width: 350px) */
@media (max-width: 350px) {
    h3 {
        font-size: 0.9rem;
    }
}

sp_widget.script:
(function() {
    input = input || {};

    function formatarNumero(valor) {
        if (typeof valor !== 'number') {
            valor = parseFloat(valor);
        }

        return valor.toFixed(2) // fixa duas casas decimais
                    .replace('.', ',') // troca ponto decimal por vírgula
                    .replace(/\B(?=(\d{3})+(?!\d))/g, '.'); // insere separadores de milhar
    }

    var anoFiltro = input.ano || "";
    var bimestreFiltro = input.bimestre || "";

    var gr = new GlideRecord('x_sded9_portal_t_0_u_resultado_primario');
    gr.addQuery('u_rpps', false);

    if (anoFiltro !== "") {
        gr.addQuery('u_ano', anoFiltro);
    }

    if (bimestreFiltro !== "") {
        gr.addQuery('u_bimestre', bimestreFiltro);
    }

    gr.query();

    var dadosAgrupados = {};
    while (gr.next()) {
        var ano = gr.getValue('u_ano');
        var bimestre = gr.getValue('u_bimestre');
        var rawValor = gr.getValue('u_resultado_primario') || "0";
        var resultado = parseFloat(rawValor) || 0;

        if (anoFiltro !== "") {
            var chave = bimestre;
            if (!dadosAgrupados[chave]) {
                dadosAgrupados[chave] = {
                    ano: ano,
                    bimestre: bimestre,
                    resultado: 0,
                    resultadoFormatado: ''
                };
            }
            dadosAgrupados[chave].resultado += resultado;
            dadosAgrupados[chave].resultadoFormatado = formatarNumero(dadosAgrupados[chave].resultado);
        } else {
            var chaveAno = ano;
            if (!dadosAgrupados[chaveAno]) {
                dadosAgrupados[chaveAno] = {
                    ano: ano,
                    resultado: 0,
                    resultadoFormatado: ''
                };
            }
            dadosAgrupados[chaveAno].resultado += resultado;
            dadosAgrupados[chaveAno].resultadoFormatado = formatarNumero(dadosAgrupados[chaveAno].resultado);
        }
    }

    var listaDados = [];
    for (var key in dadosAgrupados) {
        listaDados.push(dadosAgrupados[key]);
    }

    listaDados.sort(function(a, b) {
        if (a.ano !== b.ano) {
            return a.ano.localeCompare(b.ano);
        }
        if (a.bimestre && b.bimestre) {
            return parseInt(a.bimestre) - parseInt(b.bimestre);
        }
        return 0;
    });

    data.dadosGraficoBarras = listaDados;
})();
